import { useState, useRef, FormEvent } from 'react';
import type { Activity, Category } from '../types';
import { CATEGORIES, CATEGORY_LABELS } from '../types';

interface ActivityFormProps {
  activity?: Activity;
  onSubmit: (activity: Omit<Activity, 'id' | 'createdAt' | 'updatedAt'>) => void;
  onCancel: () => void;
}

export function ActivityForm({ activity, onSubmit, onCancel }: ActivityFormProps) {
  const [name, setName] = useState(activity?.name ?? '');
  const [description, setDescription] = useState(activity?.description ?? '');
  const [category, setCategory] = useState<Category>(activity?.category ?? 'other');
  const [dailyGoal, setDailyGoal] = useState<string>(activity?.dailyGoal?.toString() ?? '');

  const nameRef = useRef<HTMLInputElement>(null);
  const descriptionRef = useRef<HTMLTextAreaElement>(null);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();

    if (!name.trim()) return;

    const activityData: Omit<Activity, 'id' | 'createdAt' | 'updatedAt'> = {
      name: name.trim(),
      description: description.trim() || undefined,
      category,
      dailyGoal: dailyGoal ? parseInt(dailyGoal, 10) : undefined,
    };

    onSubmit(activityData);
  };

  return (
    <form onSubmit={handleSubmit} className="activity-form">
      <div className="form-group">
        <label htmlFor="activity-name">Name</label>
        <input
          id="activity-name"
          ref={nameRef}
          type="text"
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="Aktivität eingeben"
          required
          autoFocus
        />
      </div>

      <div className="form-group">
        <label htmlFor="activity-description">Beschreibung (optional)</label>
        <textarea
          id="activity-description"
          ref={descriptionRef}
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="Zusätzliche Details..."
          rows={2}
        />
      </div>

      <div className="form-row">
        <div className="form-group">
          <label htmlFor="activity-category">Kategorie</label>
          <select
            id="activity-category"
            value={category}
            onChange={(e) => setCategory(e.target.value as Category)}
          >
            {CATEGORIES.map((cat) => (
              <option key={cat} value={cat}>
                {CATEGORY_LABELS[cat]}
              </option>
            ))}
          </select>
        </div>

        <div className="form-group">
          <label htmlFor="activity-goal">Tagesziel (optional)</label>
          <input
            id="activity-goal"
            type="number"
            min="1"
            value={dailyGoal}
            onChange={(e) => setDailyGoal(e.target.value)}
            placeholder="-"
          />
        </div>
      </div>

      <div className="form-actions">
        <button type="button" onClick={onCancel}>
          Abbrechen
        </button>
        <button type="submit">
          {activity ? 'Speichern' : 'Hinzufügen'}
        </button>
      </div>
    </form>
  );
}

import { useState } from 'react';
import type { Activity } from '../types';

interface ActivityItemProps {
  activity: Activity;
  isCompleted: boolean;
  onToggle: (id: string) => void;
  onEdit: (activity: Activity) => void;
  onDelete: (id: string) => void;
}

export function ActivityItem({ 
  activity, 
  isCompleted, 
  onToggle, 
  onEdit, 
  onDelete 
}: ActivityItemProps) {
  const [isDeleting, setIsDeleting] = useState(false);

  const handleDelete = () => {
    if (window.confirm(`Möchten Sie "${activity.name}" wirklich löschen?`)) {
      setIsDeleting(true);
      onDelete(activity.id);
    }
  };

  return (
    <div 
      className={`activity-item ${isCompleted ? 'completed' : ''}`}
      role="listitem"
      aria-label={`${activity.name}, ${isCompleted ? 'erledigt' : 'offen'}`}
    >
      <div className="activity-content">
        <button
          type="button"
          className="checkbox-btn"
          aria-checked={isCompleted}
          onClick={() => onToggle(activity.id)}
          title={isCompleted ? 'Als offen markieren' : 'Als erledigt markieren'}
        >
          <span className="checkbox" aria-hidden="true">
            {isCompleted ? '✓' : '○'}
          </span>
        </button>

        <div className="activity-details">
          <h3 className="activity-name">{activity.name}</h3>
          {activity.description && (
            <p className="activity-description">{activity.description}</p>
          )}
          {activity.dailyGoal && (
            <div className="activity-goal">
              Tagesziel: {activity.dailyGoal}
            </div>
          )}
        </div>
      </div>

      <div className="activity-actions">
        <button
          type="button"
          onClick={() => onEdit(activity)}
          aria-label="Bearbeiten"
          title="Bearbeiten"
        >
          ✏️
        </button>
        <button
          type="button"
          onClick={handleDelete}
          disabled={isDeleting}
          aria-label="Löschen"
          title="Löschen"
        >
          🗑️
        </button>
      </div>
    </div>
  );
}

import type { Activity } from '../types';

interface DashboardProps {
  activities: Activity[];
  completedCount: number;
  totalCount: number;
}

export function Dashboard({ activities, completedCount, totalCount }: DashboardProps) {
  const progress = totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0;

  // Nach Kategorien gruppieren
  const byCategory = activities.reduce<Record<string, { total: number; completed: number }>>(
    (acc, activity) => {
      const cat = activity.category;
      if (!acc[cat]) {
        acc[cat] = { total: 0, completed: 0 };
      }
      acc[cat].total += 1;
      return acc;
    },
    {}
  );

  return (
    <section className="dashboard" aria-labelledby="dashboard-heading">
      <h2 id="dashboard-heading">Übersicht</h2>

      <div className="stats-grid">
        <div className="stat-card">
          <div className="stat-value">{completedCount}</div>
          <div className="stat-label">Erledigt</div>
        </div>

        <div className="stat-card">
          <div className="stat-value">{totalCount - completedCount}</div>
          <div className="stat-label">Offen</div>
        </div>

        <div className="stat-card">
          <div className="stat-value">{progress}%</div>
          <div className="stat-label">Fortschritt</div>
        </div>
      </div>

      <div className="progress-bar" role="progressbar" aria-valuenow={progress} aria-valuemin={0} aria-valuemax={100}>
        <div 
          className="progress-fill" 
          style={{ width: `${progress}%` }}
        />
      </div>

      <h3>Nach Kategorie</h3>
      <div className="category-grid">
        {Object.entries(byCategory).map(([category, counts]) => (
          <div key={category} className="category-item">
            <span className="category-name">{category}</span>
            <span className="category-count">
              {counts.completed} / {counts.total}
            </span>
          </div>
        ))}
      </div>
    </section>
  );
}

import { useState, useEffect } from 'react';

interface DateNavigatorProps {
  currentDate: Date;
  onDateChange: (date: Date) => void;
}

export function DateNavigator({ currentDate, onDateChange }: DateNavigatorProps) {
  const [inputValue, setInputValue] = useState('');

  useEffect(() => {
    const formatted = currentDate.toISOString().split('T')[0];
    setInputValue(formatted);
  }, [currentDate]);

  const formatDisplayDate = (date: Date) => {
    return date.toLocaleDateString('de-DE', {
      weekday: 'long',
      day: 'numeric',
      month: 'long',
      year: 'numeric',
    });
  };

  const handlePrevDay = () => {
    const newDate = new Date(currentDate);
    newDate.setDate(newDate.getDate() - 1);
    onDateChange(newDate);
  };

  const handleNextDay = () => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const newDate = new Date(currentDate);
    // Nächsten Tag, aber nicht weiter als heute + 1 Tag (für zukünftige Ansicht)
    if (newDate < new Date(today.getTime() + 24 * 60 * 60 * 1000)) {
      newDate.setDate(newDate.getDate() + 1);
      onDateChange(newDate);
    }
  };

  const handleToday = () => {
    onDateChange(new Date());
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInputValue(e.target.value);
  };

  const handleInputBlur = () => {
    const parts = inputValue.split('-');
    if (parts.length === 3) {
      const [year, month, day] = parts.map(Number);
      if (!isNaN(year) && !isNaN(month) && !isNaN(day)) {
        const newDate = new Date(year, month - 1, day);
        if (!isNaN(newDate.getTime())) {
          onDateChange(newDate);
        }
      }
    }
  };

  const isFutureDate = () => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return currentDate > today;
  };

  return (
    <nav className="date-navigator" aria-label="Datumsnavigation">
      <button
        type="button"
        onClick={handlePrevDay}
        aria-label="Vorheriger Tag"
        title="Vorheriger Tag"
      >
        ←
      </button>

      <div className="date-display">
        <div className="date-weekday">{formatDisplayDate(currentDate)}</
        </div>
        <input
          type="date"
          value={inputValue}
          onChange={handleInputChange}
          onBlur={handleInputBlur}
          aria-label="Datum auswählen"
        />
        {isFutureDate() && (
          <span className="future-indicator" title="Zukünftiges Datum">
            (Zukunft)
          </span>
        )}
      </div>

      <button
        type="button"
        onClick={handleToday}
        aria-label="Heute"
        title="Heute"
      >
        heute
      </button>

      <button
        type="button"
        onClick={handleNextDay}
        aria-label="Nächster Tag"
        title="Nächster Tag"
      >
        →
      </button>
    </nav>
  );
}

