.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.stat-card {
  background: var(--color-card-bg);
  border-radius: 0.5rem;
  padding: 1rem;
  text-align: center;
}

.stat-value {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-text);
}

.stat-label {
  font-size: 0.875rem;
  color: var(--color-secondary);
  margin-top: 0.25rem;
}

.progress-bar {
  height: 0.5rem;
  background: var(--color-border);
  border-radius: 0.25rem;
  overflow: hidden;
  margin-bottom: 1.5rem;
}

.progress-fill {
  height: 100%;
  background: var(--color-primary);
  transition: width 0.3s ease;
}

.category-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 0.5rem;
}

.category-item {
  display: flex;
  justify-content: space-between;
  padding: 0.5rem;
  background: var(--color-card-bg);
  border-radius: 0.25rem;
  font-size: 0.875rem;
}

/* Date Navigator */
.date-navigator {
  display: flex;
  align-items: center;
  gap: 0.5rem;
